def t(lang: str, key: str, default: str = None, **kwargs):
    """Get localized string. Fallback: other locale, then default, then key."""
    if lang not in LOCALES:
        lang = "en"
    s = LOCALES[lang].get(key)
    if s is None:
        s = LOCALES["en"].get(key)
    if s is None:
        s = default if default is not None else key
    if not isinstance(s, str):
        return s
    for k, v in kwargs.items():
        s = s.replace("{" + k + "}", str(v))
    return s

